// [AI로 분석] — 엔티티·개념에 반영(옛 raw 페이지는 서버가 대체). modelOverride=팝업에서 고른 모델.
async function analyzeItem(s: SourceItem, reanalyze = false, modelOverride?: string, diarize = false) {
  if (acting.has(s.id)) return;
  const chosen = modelOverride || (modelUserPicked ? analyzeModelId : undefined); // 고른 모델 우선, 없으면 자동(서버 결정)
  // ★음성·영상 재분석★: 회의록 처리는 서버가 자동(전사 소스), 화자 구분만 팝업에서 고른 값(diarize 파라미터).
  const isAudio = isTranscribedExtractor(s.extractor);
  const startedAt = Date.now();
  const ctrl = new AbortController();
  setActing((a) => new Map(a).set(s.id, { label: modelLabel(chosen || s.recoModel || analyzeModelId), at: startedAt, ctrl }));
  setNotes((n) => { const c = { ...n }; delete c[s.id]; return c; });
  try {
    const res = await fetch(`/api/materials/${s.id}/analyze`, {
      method: "POST", headers: { "content-type": "application/json" },
      body: JSON.stringify({ mode: "llm", reanalyze, model: chosen || undefined, diarize: (isAudio && diarize) || undefined }),
      signal: ctrl.signal,
    });
    const data = await res.json();
    const took = ` · ${fmtElapsed(Date.now() - startedAt)}`; // 완료/실패 시 최종 경과 시간
    if (!res.ok) setNotes((n) => ({ ...n, [s.id]: `분석 실패: ${data.error || ""}${took}` }));
    else if (data.queued) setNotes((n) => ({ ...n, [s.id]: "분석 예약됨 · 백그라운드에서 처리 중" })); // ★L2 비동기★
    else {
      const sw = data.fallback ? " · 백업 모델로 자동 전환됨" : "";
      const md = data.usedModel ? ` · 모델 ${modelLabel(data.usedModel)}` : "";
      const dup = data.status === "SKIPPED_DUP";
      const msg = dup ? "이미 분석된 자료입니다"
        : data.status === "NEEDS_REVIEW" ? "검토 대기" : (reanalyze ? "다시 분석 반영됨" : "AI 분석 반영됨");
      setNotes((n) => ({ ...n, [s.id]: msg + md + sw + (dup ? "" : took) }));
    }
  } catch (e) {
    const aborted = e instanceof Error && e.name === "AbortError";
    setNotes((n) => ({ ...n, [s.id]: `${aborted ? "분석 취소됨" : `오류: ${toUserMessage(e)}`} · ${fmtElapsed(Date.now() - startedAt)}` }));
  } finally {
    markDuration(s.id, Date.now() - startedAt); // 완료/실패 최종 소요 — 배지에 남김
    setActing((a) => { const c = new Map(a); c.delete(s.id); return c; });
    await load(); onDataChanged?.(); // 새 엔티티/개념 페이지 → 위키 트리/리더 갱신
  }
}

// ★원본 그대로 추가★(토큰 0) — AI 정리 없이 원문 텍스트를 위키 페이지로 보존. 분석이 너무 커서 실패한 자료의
//   권장 대안(출력 길이 한도와 무관). 기존 FAILED 잡은 최신 APPLIED(RAW_IMPORT) 잡으로 자연스레 대체된다.
async function fileAsRaw(s: SourceItem) {
  if (acting.has(s.id)) return;
  if (!await confirmDialog(`「${s.title}」을(를) 원본 그대로 추가할까요?\nAI 정리 없이 원문 텍스트를 위키 페이지로 보존합니다. (토큰 0)`)) return;
  const ctrl = new AbortController();
  setActing((a) => new Map(a).set(s.id, { label: "", at: Date.now(), ctrl })); // 원본 그대로 = 모델 없음
  setNotes((n) => { const c = { ...n }; delete c[s.id]; return c; });
  try {
    const res = await fetch(`/api/materials/${s.id}/analyze`, {
      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ mode: "raw" }), signal: ctrl.signal,
    });
    const data = await res.json();
    setNotes((n) => ({ ...n, [s.id]: res.ok ? "원본 그대로 추가됨 · 토큰 0" : `추가 실패: ${data.error || ""}` }));
  } catch (e) {
    setNotes((n) => ({ ...n, [s.id]: `오류: ${toUserMessage(e)}` }));
  } finally {

