101	          return elapsed ? `${label} · ${elapsed}` : label;
102	        })();
103	        const note = notes[s.id];
104	        return (
105	          <div key={s.id} className="mat-item-row" style={{ paddingLeft: 16 }} onClick={() => onSeen(s)}>
