const canAnalyze = !archivedMode && (isRaw || s.status === "UNANALYZED" || (s.status === "PENDING" && s.hasText));
// [다시 분석] 대상: 이미 분석된 자료(원본 보존하며 엔티티·개념 갱신).
const canReanalyze = !archivedMode && s.status === "APPLIED" && !isRaw;
const act = acting.get(s.id);
const busy = !!act;
const serverProc = !busy && (s.status === "RUNNING" || s.status === "APPLYING" || s.status === "QUEUED"); // 다른 세션·비동기 큐 등 서버측 처리 중
const isCanceling = !!canceling && canceling.has(s.id) && (busy || serverProc); // 취소 누른 직후~서버가 취소 확정(상태 전환)하기 전까지
// 처리 중 모델 + 경과 시간 — 로컬(이 클라가 누름) 시작시각 우선, 없으면 ★서버 잡 시작시각(startedAt)★.
//   → 비동기 큐·새로고침·다른 세션이 시작한 작업도 경과가 1초마다 증가(이전엔 클라 시작분만 카운트).
const procLabel = busy ? act.label : (serverProc ? modelLabel(s.model) : "");
// 서버 경과는 QUEUED·RUNNING(비동기 인제스트)만 — APPLYING(검토승인)은 잡 createdAt이 오래돼 경과가 틀림.
const startMs = busy ? act.at : (serverProc && (s.status === "QUEUED" || s.status === "RUNNING") && s.startedAt ? Date.parse(s.startedAt) : 0);
const elapsed = (busy || serverProc) && startMs ? fmtElapsed(now - startMs) : "";
// 처리 배지 문구: 단계(phase)와 경과를 함께. QUEUED는 phase(대기 중/요약 k/N), 그 외는 '처리 중 {모델} · {phase}'.
const procText = isCanceling ? "취소 중…" : (() => {
  const label = s.status === "QUEUED" ? (s.phase || "대기 중") : `처리 중${procLabel ? ` ${procLabel}` : ""}${s.phase ? ` · ${s.phase}` : ""}`;
  return elapsed ? `${label} · ${elapsed}` : label;
})();
const note = notes[s.id];
return (
  <div key={s.id} className="mat-item-row" style={{ paddingLeft: 16 }} onClick={() => onSeen(s)}>
    <div className="mat-item tree">
      <FIcon size={17} className="mat-ficon" />
      <div className="mat-item-main">
        <div className="mat-item-title" title={s.title}>{s.title}</div>
        <div className="mat-item-sub"><span className="mat-ext">{typeLabel(s.type)}</span> · <span title={kstStamp(new Date(s.createdAt))}>{kstTimeStr(new Date(s.createdAt))}</span>
          {s.byteSize != null && <> · <span title={s.extractor && (s.extractor.startsWith("groq-") || s.extractor.startsWith("gemini-")) ? "원본 음성·영상 용량" : "원본 파일 용량"}>{fmtBytes(s.byteSize)}</span></>}
          {isRecent(s.createdAt) && !seenNew(`mat:${s.id}`) && <span className="new-badge" title={`최근 ${RECENT_DAYS}일 이내 추가됨 (클릭하면 사라짐)`}>N</span>}
          {s.uploader
            ? <> · <span className="mat-uploader" title={s.anonymous ? "익명 요청 자료 — 관리자에게만 실명 표시(감사)" : "업로더"}>
                <Avatar className="mat-uploader-av" initials={s.uploader.avatar.initials} color={s.uploader.avatar.color} imageUrl={s.uploader.avatar.imageUrl} />
                {s.uploader.name}{s.anonymous ? " 🔒" : ""}</span></>
            : s.anonymous ? <> · <span className="mat-uploader anon" title="익명 기여자 (작성자는 감사 기록에 유지됨)">익명 기여자</span></> : null}
          {/* ★처리 중엔 '처리 중 {모델}', 완료 후엔 '분석 {모델}'★ — 어떤 모델이 도는지/분석했는지. */}
          {busy || serverProc ? (
            <span className="mat-model-badge proc" title={isCanceling ? "취소 중" : "처리 중"}>{procText}</span>
          ) : s.model && ((s.status === "APPLIED" && !isRaw) || s.status === "NEEDS_REVIEW") ? (
            <span className="mat-model-badge" title="이 자료를 분석한 모델">분석 {modelLabel(s.model)}{durations.has(s.id) ? ` · ${fmtElapsed(durations.get(s.id)!)}` : ""}</span>
          ) : null}
          {/* ★음성·영상 전사 출처★ — Gemini 전사는 외부 학습 경고(민감 자료 주의), Groq는 외부 전송(미학습). 분석 모델과 별개. */}
          {s.extractor?.startsWith("gemini-") ? (
            <span className="mat-model-badge warn" title="이 자료는 Gemini로 음성을 텍스트로 변환함 — 오디오가 Google로 전송·학습됩니다. 민감 자료엔 쓰지 마세요.">Gemini 텍스트 변환 · 외부학습</span>
          ) : s.extractor?.startsWith("groq-") ? (
            <span className="mat-model-badge" title="이 자료는 Groq Whisper로 음성을 텍스트로 변환함(외부 전송, 학습엔 미사용)">Groq 텍스트 변환</span>
          ) : null}

