1	import { NextResponse } from "next/server";
2	import { getSessionUser } from "@/lib/auth/session";
3	import { assertScopeAllowed, canManageScope, scopeWikiPrefix } from "@/lib/acl/scope";
4	import { prisma } from "@/lib/db";
5	import { storeForAnalysis, storeRawOnly } from "@/lib/ingest";
6	import { extractAsset, SUPPORTED_EXTS, STT_EXTS } from "@/lib/extract";
7	import { STT_FFMPEG_EXTS, sttAvailable, sttAsync, isTranscribedExtractor } from "@/lib/stt";
8	import { CONVERT_ONLY_EXTS, libreOfficeAvailable, ffmpegAvailable } from "@/lib/convert";
9	import { currentUploadPolicy, uploadPolicyForModel, uploadPoliciesForModels } from "@/lib/uploadPolicy";
10	import { listSelectableModels, resolveIngestModel, ingestModelChoice, recommendIngestModel, pickIngestModel } from "@/lib/models";
11	import { disabledModelIds, enabledModelIds } from "@/lib/modelSettings";
12	import { modelFor } from "@/lib/anthropic";
13	import { avatarForUser } from "@/lib/avatar";
14	import { streamToTempFile, cleanupTemp, UploadTooLargeError } from "@/lib/upload-stream";
15	import { readFile } from "node:fs/promises";
16	
17	// 업로드 용량 상한(MB). 음성·영상은 L1 청크 전사로 긴 회의 수용(100), 문서는 L3a 스트리밍으로 상향(200).
18	//   ★500MB까지는 L3b 입력 청킹(거대 문서 분석) 후 — docs/PLAN-large-files-and-chunking §11.3.
19	//   큰 파일(STREAM_THRESHOLD 초과)은 클라가 raw-body 스트리밍으로 보내 RAM 통적재를 피한다(§11.2).
20	const CAP_MB_AUDIO_VIDEO = 100;
21	const CAP_MB_DOC = 500; // L3a 스트리밍 업로드 + L3b 응축(거대 텍스트 분석 가능) → 500MB. Ingress 512m와 정합.
22	const STREAM_THRESHOLD = 25 * 1024 * 1024; // 이 이상은 raw-body 스트리밍 권장(클라/서버 공통 기준)
23	
24	// 자료 업로드(텍스트/MD) → 인제스트 → 위키. ACL 강제지점3(인제스트 적용). docs/06·docs/07 §2.
25	export const runtime = "nodejs";
26	export const maxDuration = 600; // 무거운 자료를 추론 모델(claude/codex)이 분석할 때 길어질 수 있음(타임아웃 600초와 정렬)
27	
28	// GET: scope의 최근 자료 목록
29	export async function GET(req: Request) {
30	  const user = await getSessionUser();
31	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
32	  const scope = new URL(req.url).searchParams.get("scope") ?? "";
33	  try {
34	    await assertScopeAllowed(user, scope);
35	  } catch {
36	    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
37	  }
38	  const wikiScope = scopeWikiPrefix(scope);
39	  // 기본은 활성(archivedAt=null)만. ?archived=1 → 아카이브된 자료(복원/영구삭제 뷰).
40	  const showArchived = new URL(req.url).searchParams.get("archived") === "1";
41	  const sources = await prisma.source.findMany({
42	    where: { teamScope: wikiScope, archivedAt: showArchived ? { not: null } : null },
43	    orderBy: { id: "desc" },
44	    take: 30,
45	    include: { ingestJobs: { orderBy: { id: "desc" }, take: 1 } },
46	  });
47	  const queryModels = await listSelectableModels(); // ★결제 전 API Claude 숨김★(드롭다운용)
48	  const canManage = await canManageScope(user, wikiScope); // 아카이브·영구삭제 권한(룸 관리자)
49	  // 소스별 '자동선택 모델'(recoModel)을 동봉 — 셋·기본값을 ★1회만★ 조회하고 동기 코어로 소스마다 계산.
50	  const [disabled, explicitOn, fallback] = await Promise.all([disabledModelIds(), enabledModelIds(), ingestModelChoice()]);
51	  // 업로더 표시 — id→이름·아바타. ★익명이어도 관리자/룸관리자는 실명 확인★(감사기록 유지), 동료에겐 '익명 기여자'.
52	  const uploaderIds = [...new Set(sources.map((s) => s.uploadedBy).filter((x): x is number => x != null))];
53	  const uploaders = uploaderIds.length
54	    ? await prisma.user.findMany({ where: { id: { in: uploaderIds } }, select: { id: true, name: true, email: true, avatarColor: true, avatarMime: true } })
55	    : [];
56	  const userById = new Map(uploaders.map((u) => [u.id, u]));
57	  const canReveal = canManage || user.role === "ADMIN";
58	  return NextResponse.json({
59	    canManage,
60	    sources: sources.map((s) => {
61	      let prov: { hasText?: boolean; looksOrganized?: boolean } = {};
62	      try { prov = JSON.parse(s.provenance || "{}"); } catch { /* */ }
63	      const transcribed = isTranscribedExtractor(s.extractor); // 전사 소스 = byteSize 휴리스틱 제외 + Groq 분석 기본
64	      return {
65	        id: s.id,
66	        title: s.title,
67	        type: s.type,
68	        createdAt: s.createdAt.toISOString(),
69	        archived: Boolean(s.archivedAt),
70	        rawEvicted: Boolean(s.rawEvictedAt), // L4: 원본 정리됨(원본 열기 비활성·배지) — 지식·추출본은 유지
71	
72	        // 잡이 있으면 그 상태, 미분석 보존(UNANALYZED)이면 그대로, 그 외 잡 없는 신규 소스 = '분석 대기'(PENDING).
73	        status: s.ingestJobs[0]?.status ?? (s.extractStatus === "UNANALYZED" ? "UNANALYZED" : "PENDING"),
74	        confidence: s.ingestJobs[0]?.confidence ?? null,
75	        gate: s.ingestJobs[0]?.gate ?? null,
76	        error: s.ingestJobs[0]?.error ?? null, // 실패(FAILED) 사유 전문 — UI에서 표시·복사
77	        model: s.ingestJobs[0]?.model ?? null, // 분석에 쓰인 모델(실패 진단 참고)
78	        phase: s.ingestJobs[0]?.phase ?? null, // L2 비동기 처리 단계(대기 중/분석…) — QUEUED/RUNNING 배지 보조
79	        progress: s.ingestJobs[0]?.progress ?? null, // L2 진행률(0~100), null=동기/미사용
80	        resultPages: s.ingestJobs[0]?.resultPages ?? null, // A-ⓕ: 이 분석이 만든 콘텐츠 페이지 수(0=새 페이지 없음→링크 숨김, null=구버전)
81	        startedAt: s.ingestJobs[0]?.createdAt?.toISOString() ?? null, // 잡 시작(큐 적재) 시각 — ★서버 처리 경과 타이머★(클라 시작시각 없을 때)
82	        byteSize: s.byteSize ?? null, // 원본 파일 용량(업로드 바이트). 전사 소스는 오디오 바이트=원본 용량.
83	        // [AI로 분석]/[다시 분석]이 ★자동★(모델 미선택)일 때 서버가 고를 모델 — '처리 중 {모델}' 배지를 정확히.
84	        // ★전사 소스(groq-/gemini-)는 byteSize=오디오 바이트라 텍스트 길이 아님 → 크기 휴리스틱 제외 + Groq 분석 기본.
85	        recoModel: pickIngestModel({ type: s.type, chars: transcribed ? undefined : (s.byteSize ?? undefined), transcribed }, { disabled, explicitOn, fallback }).model,
86	        extractStatus: s.extractStatus ?? null,
87	        extractor: s.extractor ?? null,
88	        hasExtracted: Boolean(s.normalizedPath),
89	        hasText: Boolean(prov.hasText ?? s.normalizedPath), // '원본 그대로' 가능 여부
90	        looksOrganized: Boolean(prov.looksOrganized), // 이미 위키 형식 → '원본 그대로' 추천
91	        anonymous: s.anonymous, // 동료 표시용 익명 여부
92	        // 업로더 표시: 익명+비관리자면 숨김(null→UI '익명 기여자'). 관리자/룸관리자는 익명이어도 실명+아바타.
93	        uploader: (() => {
94	          const up = s.uploadedBy != null ? userById.get(s.uploadedBy) : null;
95	          if (!up || (s.anonymous && !canReveal)) return null; // 동료엔 익명 → null
96	          return { name: up.name || up.email, avatar: avatarForUser(up) }; // {name, avatar:{initials,color,imageUrl}}
97	        })(),
98	      };
99	    }),
100	    // LibreOffice 변환 사이드카(4j)가 켜진 환경에서만 추가 수락되는 포맷 — UI 안내·accept 확장용
101	    convertExts: libreOfficeAvailable() ? CONVERT_ONLY_EXTS : [],
102	    // 업로드 정책(기본 공급자 기준 허용 포맷·안내) — 모델 미선택 시 폴백
103	    policy: currentUploadPolicy(),
104	    // 자료 탭 모델 선택기용: 선택 가능 모델 + ★모델 id별★ 업로드 정책(선택 시 즉시 전환) + 기본 모델
105	    models: queryModels,
106	    policies: uploadPoliciesForModels(queryModels),
107	    defaultModel: modelFor("ingest"),
108	    // [AI로 분석]이 자동으로 쓸 모델 + 사유(툴팁). 사용자는 모델을 고르지 않는다.
109	    analyzeModel: fallback,
110	  });
111	}
112	
113	type SessionUser = NonNullable<Awaited<ReturnType<typeof getSessionUser>>>;
114	interface StageOpts { scope: string; title: string; anonymous: boolean; diarize: boolean; modelField: string }
115	
116	// 업로드 버퍼 1건을 ★스테이징★(게이팅→추출→보관, 토큰 0)한다. multipart·raw-body 양쪽이 공유.
117	//   ACL 강제지점3·형식/모델 게이팅·용량 cap·추출(docs/17)·원본 보존을 한 곳에 모아 경로 간 불일치를 막는다
118	//   (전수 점검 원칙 [[sweep-all-dont-claim-fixed]] — 같은 불변식을 두 진입점에 중복 구현하지 않음).
119	async function stageBuffer(user: SessionUser, buf: Buffer, filename: string, mimeType: string, opts: StageOpts): Promise<NextResponse> {
120	  const { scope, anonymous, diarize, modelField } = opts;
121	  try {
122	    await assertScopeAllowed(user, scope); // ACL 강제지점3
123	  } catch {
124	    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
125	  }
126	  // 사용자가 자료 탭에서 고른 인제스트 모델(검증·폴백) → ★그 모델★ 능력 기준으로 게이팅·인제스트.
127	  const picked = await resolveIngestModel(modelField || undefined);
128	  const ext = (filename.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "";
129	  const pol = uploadPolicyForModel(picked.model, picked.provider);
130	  const isImg = ["image/png", "image/jpeg", "image/gif", "image/webp"].includes(mimeType) || ["png", "jpg", "jpeg", "gif", "webp"].includes(ext);
131	  const isPdf = mimeType === "application/pdf" || ext === "pdf";
132	  // 게이팅(서버 강제): ① 형식 자체 미지원이면 400, ② 형식은 지원하나 선택 모델로는 불가면 415.
133	  //   음성·영상(STT)은 SUPPORTED_EXTS엔 없고 키 있을 때만 허용 → 1차 게이트에도 포함(uploadPolicy와 동일 조건).
134	  const sttExts = sttAvailable() ? [...STT_EXTS, ...(ffmpegAvailable() ? STT_FFMPEG_EXTS : [])] : [];
135	  const allExts = [...SUPPORTED_EXTS, ...(libreOfficeAvailable() ? CONVERT_ONLY_EXTS : []), ...sttExts];
136	  if (!allExts.includes(ext)) {
137	    return NextResponse.json({ error: `지원하지 않는 형식입니다(.${ext || "?"}). 지원: ${allExts.join(", ")}` }, { status: 400 });
138	  }
139	  if (!pol.exts.includes(ext)) {
140	    return NextResponse.json({ error: pol.note }, { status: 415 });
141	  }
142	  // 음성·영상: ★긴 음성 청크 전사(L1)★로 Groq 25MB 한도를 우회하므로 100MB 허용. 문서는 L3a 스트리밍으로 200MB(§11).
143	  const isAudioVideo = mimeType.startsWith("audio/") || mimeType.startsWith("video/") || STT_EXTS.includes(ext) || STT_FFMPEG_EXTS.includes(ext);
144	  const capMb = isAudioVideo ? CAP_MB_AUDIO_VIDEO : CAP_MB_DOC;
145	  if (buf.byteLength > capMb * 1024 * 1024) {
146	    return NextResponse.json({ error: `파일은 ${capMb}MB 이하만 가능합니다.${isAudioVideo ? " 더 긴 음성·영상은 잘라서 올려주세요." : ""}` }, { status: 400 });
147	  }
148	  const wikiScope = scopeWikiPrefix(scope);
149	  const title = opts.title.trim() || filename.replace(/\.[^.]+$/, "") || "자료";
150	  const rawExt = ext || (isPdf ? "pdf" : "bin");
151	  const typeLabel = isPdf ? "PDF" : isImg ? "IMAGE" : (ext ? ext.toUpperCase() : "FILE");
152	  const meta = { mimeType: mimeType || undefined, byteSize: buf.byteLength, originalName: filename };
153	  try {
154	    // ★J 전사 비동기화(ship-dark)★: STT_ASYNC면 음성·영상은 ★업로드 시 전사하지 않고★ raw만 스테이징한다.
155	    //   [분석] 단계에서 워커가 raw에서 전사(analyzeSource의 isAudioSrc·!normalizedPath 분기) → 진행률·타이머 일관.
156	    //   기본 OFF면 아래 동기 전사(현행) 그대로. (긴 음성 업로드 무진행 대기 해소 — docs PLAN-multi-upload §J)
157	    if (sttAsync() && isAudioVideo) {
158	      const result = await storeForAnalysis({
159	        scope: wikiScope, title, type: typeLabel, text: "", userId: user.id, anonymous, rawBytes: buf, rawExt,
160	        ...meta, extractor: "stt-pending", extractStatus: "NONE",
161	      });
162	      return NextResponse.json({ ...result, extractor: "stt-pending", recommended: await recommendIngestModel({ type: typeLabel, transcribed: true }) });
163	    }
164	    // ★스테이징★ — 추출(토큰0)·원본 보관만. LLM 분석은 사용자가 목록에서 [분석] 버튼을 눌렀을 때.
165	    // 1) 추출 시도(텍스트 포맷·텍스트 PDF·오피스) — 성공 시 정규화 텍스트도 보관(분석/원본그대로가 재사용).
166	    const ex = await extractAsset(buf, filename, mimeType, { diarize });
167	    if (ex.text.trim() && ex.quality !== "none") {
168	      const result = await storeForAnalysis({
169	        scope: wikiScope, title, text: ex.text, type: typeLabel, userId: user.id, anonymous, rawBytes: buf, rawExt,
170	        ...meta, extractor: ex.extractor, extractStatus: ex.quality === "full" ? "FULL" : "PARTIAL",
171	        normalizedText: ex.text, assets: ex.assets,
172	      });
173	      return NextResponse.json({ ...result, extractor: ex.extractor, recommended: await recommendIngestModel({ chars: ex.text.length, type: typeLabel, transcribed: isTranscribedExtractor(ex.extractor) }) });
174	    }
175	    // 2) 텍스트 없음: 이미지·스캔 PDF는 비전 필요 — 비전 없는 모델 선택 시 명확히 안내(업로드 시점 게이팅 유지).
176	    if (!pol.vision) {
177	      return NextResponse.json({ error: "이 모델은 텍스트 추출만 가능합니다. 텍스트가 없는 스캔본 PDF·이미지는 Gemini나 Claude 모델을 선택해 올려주세요." }, { status: 422 });
178	    }
179	    // 비전 대상은 원본만 보관(분석 때 raw를 image/document로 첨부). 텍스트가 없어 '원본 그대로'는 불가, [분석]만.
180	    if (isImg) {
181	      const result = await storeForAnalysis({ scope: wikiScope, title, type: "IMAGE", text: "", userId: user.id, anonymous, rawBytes: buf, rawExt, ...meta, extractor: "vision", extractStatus: "NONE" });
182	      return NextResponse.json({ ...result, extractor: "vision", recommended: await recommendIngestModel({ type: "IMAGE" }) });
183	    }
184	    if (isPdf) {
185	      const result = await storeForAnalysis({ scope: wikiScope, title, type: "PDF", text: "", userId: user.id, anonymous, rawBytes: buf, rawExt: "pdf", ...meta, extractor: "pdf-vision", extractStatus: "NONE" });
186	      return NextResponse.json({ ...result, extractor: "pdf-vision", recommended: await recommendIngestModel({ type: "PDF" }) });
187	    }
188	    // 3) 추출 불가(인식했으나 본문 없음) → 원본은 보존(미분석, REQ-MAT-010)
189	    const result = await storeRawOnly({ scope: wikiScope, title, rawBytes: buf, rawExt, userId: user.id, anonymous, ...meta });
190	    return NextResponse.json({ ...result, extractor: "none", unanalyzed: true, recommended: await recommendIngestModel({ type: typeLabel }) });
191	  } catch (err) {
192	    return NextResponse.json({ error: String(err) }, { status: 500 });
193	  }
194	}
195	
196	// POST: 텍스트/MD(JSON) 또는 파일(multipart=소형 / octet-stream=대형 스트리밍) 1건 인제스트
197	export async function POST(req: Request) {
198	  const user = await getSessionUser();
199	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
200	
201	  // 업로드는 ★스테이징(추출·보관만, 토큰 0)★ — LLM/비용은 [분석] 버튼 시점에. (예산 체크는 analyze 라우트.)
202	  const ct = req.headers.get("content-type") || "";
203	
204	  // 파일 업로드(multipart): 추출 레이어(docs/17)로 정규화 → 인제스트.
205	  // 원본 바이트는 raw로 보존(열람용), 텍스트는 파서로 추출(우선), 안 되면 네이티브 모달리티 폴백.
206	  if (ct.includes("multipart/form-data")) {
207	    // 작은 파일: multipart(formData). 큰 파일은 클라가 raw-body 스트리밍으로 보낸다(아래 octet-stream 분기, §11.2).
208	    const form = await req.formData();
209	    const scope = String(form.get("scope") || "");
210	    const file = form.get("file");
211	    if (!(file instanceof File)) return NextResponse.json({ error: "파일이 필요합니다." }, { status: 400 });
212	    const buf = Buffer.from(await file.arrayBuffer());
213	    return stageBuffer(user, buf, file.name, file.type, {
214	      scope,
215	      title: String(form.get("title") || ""),
216	      anonymous: String(form.get("anonymous") || "") === "true", // 익명 업로드(표시만 숨김, uploadedBy는 유지)
217	      diarize: String(form.get("diarize") || "") === "true", // 음성·영상 화자 구분(Gemini 전용·외부학습) — STT에만 영향
218	      modelField: String(form.get("model") || ""),
219	    });
220	  }
221	
222	  // ★대용량 raw-body 스트리밍 업로드(L3a, §11.2)★ — multipart의 RAM 통적재(formData+arrayBuffer 1~2배)를 피해
223	  //   본문을 청크 단위로 임시파일에 흘려보내며 sha·크기 계산(피크 메모리=청크). 메타데이터는 쿼리스트링.
224	  //   ACL을 ★본문 받기 전★ 확인해 권한 없으면 대용량 전송을 즉시 거부. cap 초과는 스트림 중단→413.
225	  if (ct.includes("application/octet-stream")) {
226	    if (!req.body) return NextResponse.json({ error: "본문이 비었습니다." }, { status: 400 });
227	    const u = new URL(req.url);
228	    const scope = u.searchParams.get("scope") || "";
229	    const filename = u.searchParams.get("filename") || "upload.bin";
230	    try {
231	      await assertScopeAllowed(user, scope); // ACL 강제지점3 — 대용량 본문 받기 전 거부
232	    } catch {
233	      return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
234	    }
235	    const ext = (filename.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "";
236	    const isAV = STT_EXTS.includes(ext) || STT_FFMPEG_EXTS.includes(ext);
237	    const capBytes = (isAV ? CAP_MB_AUDIO_VIDEO : CAP_MB_DOC) * 1024 * 1024;
238	    let streamed;
239	    try {
240	      streamed = await streamToTempFile(req.body, capBytes, ext);
241	    } catch (err) {
242	      if (err instanceof UploadTooLargeError) {
243	        const mb = Math.round(err.limit / 1024 / 1024);
244	        return NextResponse.json({ error: `파일은 ${mb}MB 이하만 가능합니다.${isAV ? " 더 긴 음성·영상은 잘라서 올려주세요." : ""}` }, { status: 413 });
245	      }
246	      return NextResponse.json({ error: String(err) }, { status: 500 });
247	    }
248	    try {
249	      const buf = await readFile(streamed.tempPath); // 추출·저장용 1회 적재(2배 적재 제거). 4Gi limit 내(§11.1).
250	      return await stageBuffer(user, buf, filename, u.searchParams.get("mime") || "", {
251	        scope,
252	        title: u.searchParams.get("title") || "",
253	        anonymous: u.searchParams.get("anonymous") === "true",
254	        diarize: u.searchParams.get("diarize") === "true",
255	        modelField: u.searchParams.get("model") || "",
256	      });
257	    } finally {
258	      await cleanupTemp(streamed.tempPath);
259	    }
260	  }
261	
262	  const { scope, title, text, anonymous: anonRaw } = await req.json();
263	  const anonymous = Boolean(anonRaw); // 익명(표시만 숨김)
264	  const body = typeof text === "string" ? text.trim() : "";
265	  if (typeof scope !== "string" || !body) {
266	    return NextResponse.json({ error: "scope와 본문(text)이 필요합니다." }, { status: 400 });
267	  }
268	
269	  // ACL 강제지점3: 인제스트 적용 — 허용 scope에만 쓸 수 있다
270	  try {
271	    await assertScopeAllowed(user, scope);
272	  } catch {
273	    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
274	  }
275	
276	  const wikiScope = scopeWikiPrefix(scope);
277	  const cleanTitle = (typeof title === "string" && title.trim()) || body.split("\n")[0].slice(0, 60) || "제목 없는 자료";
278	
279	  try {
280	    // 붙여넣은 텍스트도 스테이징(목록에서 [분석]/[원본 그대로] 선택). 토큰 0.
281	    const result = await storeForAnalysis({ scope: wikiScope, title: cleanTitle, text: body, type: "MD", userId: user.id, anonymous, rawBytes: Buffer.from(body, "utf8"), rawExt: "md", extractor: "text", extractStatus: "FULL", normalizedText: body });
282	    return NextResponse.json({ ...result, recommended: await recommendIngestModel({ chars: body.length, type: "MD" }) });
283	  } catch (err) {
284	    return NextResponse.json({ error: String(err) }, { status: 500 });
285	  }
286	}
