import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { assertScopeAllowed, canManageScope, scopeWikiPrefix } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { storeForAnalysis, storeRawOnly } from "@/lib/ingest";
import { extractAsset, SUPPORTED_EXTS, STT_EXTS } from "@/lib/extract";
import { STT_FFMPEG_EXTS, sttAvailable, sttAsync, isTranscribedExtractor } from "@/lib/stt";
import { CONVERT_ONLY_EXTS, libreOfficeAvailable, ffmpegAvailable } from "@/lib/convert";
import { currentUploadPolicy, uploadPolicyForModel, uploadPoliciesForModels } from "@/lib/uploadPolicy";
import { listSelectableModels, resolveIngestModel, ingestModelChoice, recommendIngestModel, pickIngestModel } from "@/lib/models";
import { disabledModelIds, enabledModelIds } from "@/lib/modelSettings";
import { modelFor } from "@/lib/anthropic";
import { avatarForUser } from "@/lib/avatar";
import { streamToTempFile, cleanupTemp, UploadTooLargeError } from "@/lib/upload-stream";
import { readFile } from "node:fs/promises";

// 업로드 용량 상한(MB). 음성·영상은 L1 청크 전사로 긴 회의 수용(100), 문서는 L3a 스트리밍으로 상향(200).
//   ★500MB까지는 L3b 입력 청킹(거대 문서 분석) 후 — docs/PLAN-large-files-and-chunking §11.3.
//   큰 파일(STREAM_THRESHOLD 초과)은 클라가 raw-body 스트리밍으로 보내 RAM 통적재를 피한다(§11.2).
const CAP_MB_AUDIO_VIDEO = 100;
const CAP_MB_DOC = 500; // L3a 스트리밍 업로드 + L3b 응축(거대 텍스트 분석 가능) → 500MB. Ingress 512m와 정합.
const STREAM_THRESHOLD = 25 * 1024 * 1024; // 이 이상은 raw-body 스트리밍 권장(클라/서버 공통 기준)

// 자료 업로드(텍스트/MD) → 인제스트 → 위키. ACL 강제지점3(인제스트 적용). docs/06·docs/07 §2.
export const runtime = "nodejs";
export const maxDuration = 600; // 무거운 자료를 추론 모델(claude/codex)이 분석할 때 길어질 수 있음(타임아웃 600초와 정렬)

// GET: scope의 최근 자료 목록
export async function GET(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const scope = new URL(req.url).searchParams.get("scope") ?? "";
  try {
    await assertScopeAllowed(user, scope);
  } catch {
    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
  }
  const wikiScope = scopeWikiPrefix(scope);
  // 기본은 활성(archivedAt=null)만. ?archived=1 → 아카이브된 자료(복원/영구삭제 뷰).
  const showArchived = new URL(req.url).searchParams.get("archived") === "1";
  const sources = await prisma.source.findMany({
    where: { teamScope: wikiScope, archivedAt: showArchived ? { not: null } : null },
    orderBy: { id: "desc" },
    take: 30,
    include: { ingestJobs: { orderBy: { id: "desc" }, take: 1 } },
  });
  const queryModels = await listSelectableModels(); // ★결제 전 API Claude 숨김★(드롭다운용)
  const canManage = await canManageScope(user, wikiScope); // 아카이브·영구삭제 권한(룸 관리자)
  // 소스별 '자동선택 모델'(recoModel)을 동봉 — 셋·기본값을 ★1회만★ 조회하고 동기 코어로 소스마다 계산.
  const [disabled, explicitOn, fallback] = await Promise.all([disabledModelIds(), enabledModelIds(), ingestModelChoice()]);
  // 업로더 표시 — id→이름·아바타. ★익명이어도 관리자/룸관리자는 실명 확인★(감사기록 유지), 동료에겐 '익명 기여자'.
  const uploaderIds = [...new Set(sources.map((s) => s.uploadedBy).filter((x): x is number => x != null))];
  const uploaders = uploaderIds.length
    ? await prisma.user.findMany({ where: { id: { in: uploaderIds } }, select: { id: true, name: true, email: true, avatarColor: true, avatarMime: true } })
    : [];
  const userById = new Map(uploaders.map((u) => [u.id, u]));
  const canReveal = canManage || user.role === "ADMIN";
  return NextResponse.json({
    canManage,
    sources: sources.map((s) => {
      let prov: { hasText?: boolean; looksOrganized?: boolean } = {};
      try { prov = JSON.parse(s.provenance || "{}"); } catch { /* */ }
      const transcribed = isTranscribedExtractor(s.extractor); // 전사 소스 = byteSize 휴리스틱 제외 + Groq 분석 기본
      return {
        id: s.id,
        title: s.title,
        type: s.type,
        createdAt: s.createdAt.toISOString(),
        archived: Boolean(s.archivedAt),
        rawEvicted: Boolean(s.rawEvictedAt), // L4: 원본 정리됨(원본 열기 비활성·배지) — 지식·추출본은 유지

        // 잡이 있으면 그 상태, 미분석 보존(UNANALYZED)이면 그대로, 그 외 잡 없는 신규 소스 = '분석 대기'(PENDING).
        status: s.ingestJobs[0]?.status ?? (s.extractStatus === "UNANALYZED" ? "UNANALYZED" : "PENDING"),
        confidence: s.ingestJobs[0]?.confidence ?? null,
        gate: s.ingestJobs[0]?.gate ?? null,
        error: s.ingestJobs[0]?.error ?? null, // 실패(FAILED) 사유 전문 — UI에서 표시·복사
        model: s.ingestJobs[0]?.model ?? null, // 분석에 쓰인 모델(실패 진단 참고)
        phase: s.ingestJobs[0]?.phase ?? null, // L2 비동기 처리 단계(대기 중/분석…) — QUEUED/RUNNING 배지 보조
        progress: s.ingestJobs[0]?.progress ?? null, // L2 진행률(0~100), null=동기/미사용
        resultPages: s.ingestJobs[0]?.resultPages ?? null, // A-ⓕ: 이 분석이 만든 콘텐츠 페이지 수(0=새 페이지 없음→링크 숨김, null=구버전)
        startedAt: s.ingestJobs[0]?.createdAt?.toISOString() ?? null, // 잡 시작(큐 적재) 시각 — ★서버 처리 경과 타이머★(클라 시작시각 없을 때)
        byteSize: s.byteSize ?? null, // 원본 파일 용량(업로드 바이트). 전사 소스는 오디오 바이트=원본 용량.
        // [AI로 분석]/[다시 분석]이 ★자동★(모델 미선택)일 때 서버가 고를 모델 — '처리 중 {모델}' 배지를 정확히.
        // ★전사 소스(groq-/gemini-)는 byteSize=오디오 바이트라 텍스트 길이 아님 → 크기 휴리스틱 제외 + Groq 분석 기본.
        recoModel: pickIngestModel({ type: s.type, chars: transcribed ? undefined : (s.byteSize ?? undefined), transcribed }, { disabled, explicitOn, fallback }).model,
        extractStatus: s.extractStatus ?? null,
        extractor: s.extractor ?? null,
        hasExtracted: Boolean(s.normalizedPath),
        hasText: Boolean(prov.hasText ?? s.normalizedPath), // '원본 그대로' 가능 여부
        looksOrganized: Boolean(prov.looksOrganized), // 이미 위키 형식 → '원본 그대로' 추천
        anonymous: s.anonymous, // 동료 표시용 익명 여부
        // 업로더 표시: 익명+비관리자면 숨김(null→UI '익명 기여자'). 관리자/룸관리자는 익명이어도 실명+아바타.
        uploader: (() => {
          const up = s.uploadedBy != null ? userById.get(s.uploadedBy) : null;
          if (!up || (s.anonymous && !canReveal)) return null; // 동료엔 익명 → null
          return { name: up.name || up.email, avatar: avatarForUser(up) }; // {name, avatar:{initials,color,imageUrl}}
        })(),
      };
    }),
    // LibreOffice 변환 사이드카(4j)가 켜진 환경에서만 추가 수락되는 포맷 — UI 안내·accept 확장용
    convertExts: libreOfficeAvailable() ? CONVERT_ONLY_EXTS : [],
    // 업로드 정책(기본 공급자 기준 허용 포맷·안내) — 모델 미선택 시 폴백
    policy: currentUploadPolicy(),
    // 자료 탭 모델 선택기용: 선택 가능 모델 + ★모델 id별★ 업로드 정책(선택 시 즉시 전환) + 기본 모델
    models: queryModels,
    policies: uploadPoliciesForModels(queryModels),
    defaultModel: modelFor("ingest"),
    // [AI로 분석]이 자동으로 쓸 모델 + 사유(툴팁). 사용자는 모델을 고르지 않는다.
    analyzeModel: fallback,
  });
}

type SessionUser = NonNullable<Awaited<ReturnType<typeof getSessionUser>>>;
interface StageOpts { scope: string; title: string; anonymous: boolean; diarize: boolean; modelField: string }

// 업로드 버퍼 1건을 ★스테이징★(게이팅→추출→보관, 토큰 0)한다. multipart·raw-body 양쪽이 공유.
//   ACL 강제지점3·형식/모델 게이팅·용량 cap·추출(docs/17)·원본 보존을 한 곳에 모아 경로 간 불일치를 막는다
//   (전수 점검 원칙 [[sweep-all-dont-claim-fixed]] — 같은 불변식을 두 진입점에 중복 구현하지 않음).
async function stageBuffer(user: SessionUser, buf: Buffer, filename: string, mimeType: string, opts: StageOpts): Promise<NextResponse> {
  const { scope, anonymous, diarize, modelField } = opts;
  try {
    await assertScopeAllowed(user, scope); // ACL 강제지점3
  } catch {
    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
  }
  // 사용자가 자료 탭에서 고른 인제스트 모델(검증·폴백) → ★그 모델★ 능력 기준으로 게이팅·인제스트.
  const picked = await resolveIngestModel(modelField || undefined);
  const ext = (filename.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "";
  const pol = uploadPolicyForModel(picked.model, picked.provider);
  const isImg = ["image/png", "image/jpeg", "image/gif", "image/webp"].includes(mimeType) || ["png", "jpg", "jpeg", "gif", "webp"].includes(ext);
  const isPdf = mimeType === "application/pdf" || ext === "pdf";
  // 게이팅(서버 강제): ① 형식 자체 미지원이면 400, ② 형식은 지원하나 선택 모델로는 불가면 415.
  //   음성·영상(STT)은 SUPPORTED_EXTS엔 없고 키 있을 때만 허용 → 1차 게이트에도 포함(uploadPolicy와 동일 조건).
  const sttExts = sttAvailable() ? [...STT_EXTS, ...(ffmpegAvailable() ? STT_FFMPEG_EXTS : [])] : [];
  const allExts = [...SUPPORTED_EXTS, ...(libreOfficeAvailable() ? CONVERT_ONLY_EXTS : []), ...sttExts];
  if (!allExts.includes(ext)) {
    return NextResponse.json({ error: `지원하지 않는 형식입니다(.${ext || "?"}). 지원: ${allExts.join(", ")}` }, { status: 400 });
  }
  if (!pol.exts.includes(ext)) {
    return NextResponse.json({ error: pol.note }, { status: 415 });
  }
  // 음성·영상: ★긴 음성 청크 전사(L1)★로 Groq 25MB 한도를 우회하므로 100MB 허용. 문서는 L3a 스트리밍으로 200MB(§11).
  const isAudioVideo = mimeType.startsWith("audio/") || mimeType.startsWith("video/") || STT_EXTS.includes(ext) || STT_FFMPEG_EXTS.includes(ext);
  const capMb = isAudioVideo ? CAP_MB_AUDIO_VIDEO : CAP_MB_DOC;
  if (buf.byteLength > capMb * 1024 * 1024) {
    return NextResponse.json({ error: `파일은 ${capMb}MB 이하만 가능합니다.${isAudioVideo ? " 더 긴 음성·영상은 잘라서 올려주세요." : ""}` }, { status: 400 });
  }
  const wikiScope = scopeWikiPrefix(scope);
  const title = opts.title.trim() || filename.replace(/\.[^.]+$/, "") || "자료";
  const rawExt = ext || (isPdf ? "pdf" : "bin");
  const typeLabel = isPdf ? "PDF" : isImg ? "IMAGE" : (ext ? ext.toUpperCase() : "FILE");
  const meta = { mimeType: mimeType || undefined, byteSize: buf.byteLength, originalName: filename };
  try {
    // ★J 전사 비동기화(ship-dark)★: STT_ASYNC면 음성·영상은 ★업로드 시 전사하지 않고★ raw만 스테이징한다.
    //   [분석] 단계에서 워커가 raw에서 전사(analyzeSource의 isAudioSrc·!normalizedPath 분기) → 진행률·타이머 일관.
    //   기본 OFF면 아래 동기 전사(현행) 그대로. (긴 음성 업로드 무진행 대기 해소 — docs PLAN-multi-upload §J)
    if (sttAsync() && isAudioVideo) {
      const result = await storeForAnalysis({
        scope: wikiScope, title, type: typeLabel, text: "", userId: user.id, anonymous, rawBytes: buf, rawExt,
        ...meta, extractor: "stt-pending", extractStatus: "NONE",
      });
      return NextResponse.json({ ...result, extractor: "stt-pending", recommended: await recommendIngestModel({ type: typeLabel, transcribed: true }) });
    }
    // ★스테이징★ — 추출(토큰0)·원본 보관만. LLM 분석은 사용자가 목록에서 [분석] 버튼을 눌렀을 때.
    // 1) 추출 시도(텍스트 포맷·텍스트 PDF·오피스) — 성공 시 정규화 텍스트도 보관(분석/원본그대로가 재사용).
    const ex = await extractAsset(buf, filename, mimeType, { diarize });
    if (ex.text.trim() && ex.quality !== "none") {
      const result = await storeForAnalysis({
        scope: wikiScope, title, text: ex.text, type: typeLabel, userId: user.id, anonymous, rawBytes: buf, rawExt,
        ...meta, extractor: ex.extractor, extractStatus: ex.quality === "full" ? "FULL" : "PARTIAL",
        normalizedText: ex.text, assets: ex.assets,
      });
      return NextResponse.json({ ...result, extractor: ex.extractor, recommended: await recommendIngestModel({ chars: ex.text.length, type: typeLabel, transcribed: isTranscribedExtractor(ex.extractor) }) });
    }
    // 2) 텍스트 없음: 이미지·스캔 PDF는 비전 필요 — 비전 없는 모델 선택 시 명확히 안내(업로드 시점 게이팅 유지).
    if (!pol.vision) {
      return NextResponse.json({ error: "이 모델은 텍스트 추출만 가능합니다. 텍스트가 없는 스캔본 PDF·이미지는 Gemini나 Claude 모델을 선택해 올려주세요." }, { status: 422 });
    }
    // 비전 대상은 원본만 보관(분석 때 raw를 image/document로 첨부). 텍스트가 없어 '원본 그대로'는 불가, [분석]만.
    if (isImg) {
      const result = await storeForAnalysis({ scope: wikiScope, title, type: "IMAGE", text: "", userId: user.id, anonymous, rawBytes: buf, rawExt, ...meta, extractor: "vision", extractStatus: "NONE" });
      return NextResponse.json({ ...result, extractor: "vision", recommended: await recommendIngestModel({ type: "IMAGE" }) });
    }
    if (isPdf) {
      const result = await storeForAnalysis({ scope: wikiScope, title, type: "PDF", text: "", userId: user.id, anonymous, rawBytes: buf, rawExt: "pdf", ...meta, extractor: "pdf-vision", extractStatus: "NONE" });
      return NextResponse.json({ ...result, extractor: "pdf-vision", recommended: await recommendIngestModel({ type: "PDF" }) });
    }
    // 3) 추출 불가(인식했으나 본문 없음) → 원본은 보존(미분석, REQ-MAT-010)
    const result = await storeRawOnly({ scope: wikiScope, title, rawBytes: buf, rawExt, userId: user.id, anonymous, ...meta });
    return NextResponse.json({ ...result, extractor: "none", unanalyzed: true, recommended: await recommendIngestModel({ type: typeLabel }) });
  } catch (err) {
    return NextResponse.json({ error: String(err) }, { status: 500 });
  }
}

// POST: 텍스트/MD(JSON) 또는 파일(multipart=소형 / octet-stream=대형 스트리밍) 1건 인제스트
export async function POST(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });

  // 업로드는 ★스테이징(추출·보관만, 토큰 0)★ — LLM/비용은 [분석] 버튼 시점에. (예산 체크는 analyze 라우트.)
  const ct = req.headers.get("content-type") || "";

  // 파일 업로드(multipart): 추출 레이어(docs/17)로 정규화 → 인제스트.
  // 원본 바이트는 raw로 보존(열람용), 텍스트는 파서로 추출(우선), 안 되면 네이티브 모달리티 폴백.
  if (ct.includes("multipart/form-data")) {
    // 작은 파일: multipart(formData). 큰 파일은 클라가 raw-body 스트리밍으로 보낸다(아래 octet-stream 분기, §11.2).
    const form = await req.formData();
    const scope = String(form.get("scope") || "");
    const file = form.get("file");
    if (!(file instanceof File)) return NextResponse.json({ error: "파일이 필요합니다." }, { status: 400 });
    const buf = Buffer.from(await file.arrayBuffer());
    return stageBuffer(user, buf, file.name, file.type, {
      scope,
      title: String(form.get("title") || ""),
      anonymous: String(form.get("anonymous") || "") === "true", // 익명 업로드(표시만 숨김, uploadedBy는 유지)
      diarize: String(form.get("diarize") || "") === "true", // 음성·영상 화자 구분(Gemini 전용·외부학습) — STT에만 영향
      modelField: String(form.get("model") || ""),
    });
  }

  // ★대용량 raw-body 스트리밍 업로드(L3a, §11.2)★ — multipart의 RAM 통적재(formData+arrayBuffer 1~2배)를 피해
  //   본문을 청크 단위로 임시파일에 흘려보내며 sha·크기 계산(피크 메모리=청크). 메타데이터는 쿼리스트링.
  //   ACL을 ★본문 받기 전★ 확인해 권한 없으면 대용량 전송을 즉시 거부. cap 초과는 스트림 중단→413.
  if (ct.includes("application/octet-stream")) {
    if (!req.body) return NextResponse.json({ error: "본문이 비었습니다." }, { status: 400 });
    const u = new URL(req.url);
    const scope = u.searchParams.get("scope") || "";
    const filename = u.searchParams.get("filename") || "upload.bin";
    try {
      await assertScopeAllowed(user, scope); // ACL 강제지점3 — 대용량 본문 받기 전 거부
    } catch {
      return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
    }
    const ext = (filename.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "";
    const isAV = STT_EXTS.includes(ext) || STT_FFMPEG_EXTS.includes(ext);
    const capBytes = (isAV ? CAP_MB_AUDIO_VIDEO : CAP_MB_DOC) * 1024 * 1024;
    let streamed;
    try {
      streamed = await streamToTempFile(req.body, capBytes, ext);
    } catch (err) {
      if (err instanceof UploadTooLargeError) {
        const mb = Math.round(err.limit / 1024 / 1024);
        return NextResponse.json({ error: `파일은 ${mb}MB 이하만 가능합니다.${isAV ? " 더 긴 음성·영상은 잘라서 올려주세요." : ""}` }, { status: 413 });
      }
      return NextResponse.json({ error: String(err) }, { status: 500 });
    }
    try {
      const buf = await readFile(streamed.tempPath); // 추출·저장용 1회 적재(2배 적재 제거). 4Gi limit 내(§11.1).
      return await stageBuffer(user, buf, filename, u.searchParams.get("mime") || "", {
        scope,
        title: u.searchParams.get("title") || "",
        anonymous: u.searchParams.get("anonymous") === "true",
        diarize: u.searchParams.get("diarize") === "true",
        modelField: u.searchParams.get("model") || "",
      });
    } finally {
      await cleanupTemp(streamed.tempPath);
    }
  }

  const { scope, title, text, anonymous: anonRaw } = await req.json();
  const anonymous = Boolean(anonRaw); // 익명(표시만 숨김)
  const body = typeof text === "string" ? text.trim() : "";
  if (typeof scope !== "string" || !body) {
    return NextResponse.json({ error: "scope와 본문(text)이 필요합니다." }, { status: 400 });
  }

  // ACL 강제지점3: 인제스트 적용 — 허용 scope에만 쓸 수 있다
  try {
    await assertScopeAllowed(user, scope);
  } catch {
    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
  }

  const wikiScope = scopeWikiPrefix(scope);
  const cleanTitle = (typeof title === "string" && title.trim()) || body.split("\n")[0].slice(0, 60) || "제목 없는 자료";

  try {
    // 붙여넣은 텍스트도 스테이징(목록에서 [분석]/[원본 그대로] 선택). 토큰 0.
    const result = await storeForAnalysis({ scope: wikiScope, title: cleanTitle, text: body, type: "MD", userId: user.id, anonymous, rawBytes: Buffer.from(body, "utf8"), rawExt: "md", extractor: "text", extractStatus: "FULL", normalizedText: body });
    return NextResponse.json({ ...result, recommended: await recommendIngestModel({ chars: body.length, type: "MD" }) });
  } catch (err) {
    return NextResponse.json({ error: String(err) }, { status: 500 });
  }
}

