// 스테이징된 소스를 ★선택한 모드★로 처리. raw는 텍스트가 있을 때만, 없으면(PDF·이미지) 자동으로 llm.
async function runProcess(sourceId: number, hasText: boolean, signal?: AbortSignal, modelOverride?: string, reTranscribe?: boolean): Promise<{ ok: boolean; note: string }> {
  const startedAt = Date.now();
  const fellBack = uploadMode === "raw" && !hasText;
  const effMode = uploadMode === "raw" && hasText ? "raw" : "llm";
