  const body = effMode === "raw" ? { mode: "raw" } : { mode: "llm", model: modelOverride ?? (modelUserPicked ? (analyzeModelId || undefined) : undefined), diarize: diarize || undefined, reTranscribe: reTranscribe || undefined };
  const res = await fetch(`/api/materials/${sourceId}/analyze`, {
    method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body), signal,
  });
  const data = await res.json();
  const took = effMode === "raw" ? "" : ` · ${fmtElapsed(Date.now() - startedAt)}`; // 완료/실패 시 최종 경과 시간
  if (!res.ok) {
    const e = String(data.error || "");
    // 무료 모델 한도를 넘는 큰 자료 → 기술적 오류 대신 ★행동 안내★(원본 그대로 / 더 작게).
    if (/\b413\b|too large|too many tokens|tokens per minute|\bTPM\b|context length|maximum context|RESOURCE_EXHAUSTED|한도/i.test(e)) {
      return { ok: false, note: "자료 크기가 커서 분석할 수 없어요(무료 모델 한도 초과). 이렇게 큰 자료는 ‘원본 그대로 추가’로 올리면 분석 없이 그대로 저장·검색됩니다. 분석이 꼭 필요하면 핵심만 텍스트(.md·.txt)로 추려 더 작게 나눠 올려주세요." + took };
    }
    return { ok: false, note: `${toUserMessage(e, "처리에 실패했어요.")}${took}` };
  }
  if (effMode === "raw") return { ok: true, note: "원본 그대로 추가됨 · 토큰 0" };
