  if (data.queued) return { ok: true, note: "분석 예약됨 · 백그라운드에서 처리 중" };
  const sw = data.fallback ? " · 백업 모델로 자동 전환됨" : "";
  const md = data.usedModel ? ` · 모델 ${modelLabel(data.usedModel)}` : "";
  const prefix = fellBack ? "텍스트 없음 → 분석함 · " : "";
