// 인제스트 잡의 ★완료까지 걸린 소요(ms)★ 계산 — 순수 함수.
//   비동기 큐(INGEST_ASYNC/STT_ASYNC)에서는 [분석] 요청이 {queued:true}로 즉시 반환되어
//   클라이언트가 측정한 소요가 ≈0(0:00)으로 박제된다. 실제 처리는 백그라운드 워커가 하므로
//   서버가 잡의 시작(createdAt=큐 적재)~마지막 갱신(updatedAt=완료)으로 소요를 계산해 준다.
//   ★종결 상태에서만★ 의미가 있다(처리 중엔 updatedAt이 진행 중간값이라 소요가 아니다).

// 더 이상 진행하지 않는 종결 상태 — 이때의 updatedAt이 곧 완료 시각.
const TERMINAL_STATUSES = new Set(["APPLIED", "NEEDS_REVIEW", "FAILED", "SKIPPED_DUP"]);

export function isTerminalJobStatus(status: string | null | undefined): boolean {
  return status != null && TERMINAL_STATUSES.has(status);
}

/** 종결 상태면 createdAt~updatedAt(ms), 아니면 null(처리 중 → 라이브 타이머가 startedAt으로 흐름). */
export function terminalJobDurationMs(
  job: { status: string | null; createdAt: Date; updatedAt: Date } | null | undefined,
): number | null {
  if (!job || !isTerminalJobStatus(job.status)) return null;
  return Math.max(0, job.updatedAt.getTime() - job.createdAt.getTime());
}

