    expect(terminalJobDurationMs({ status: "APPLIED", createdAt: t0, updatedAt: t90 })).toBe(90_000);
  });

  it("검토대기·실패·중복도 종결로 보고 소요를 계산한다", () => {
    for (const status of ["NEEDS_REVIEW", "FAILED", "SKIPPED_DUP"]) {
      expect(terminalJobDurationMs({ status, createdAt: t0, updatedAt: t90 })).toBe(90_000);
    }
  });

  it("★처리 중(QUEUED/RUNNING)은 null★ — updatedAt이 진행 중간값이라 소요가 아님(라이브 타이머가 흐름)", () => {
    expect(terminalJobDurationMs({ status: "QUEUED", createdAt: t0, updatedAt: t90 })).toBeNull();
    expect(terminalJobDurationMs({ status: "RUNNING", createdAt: t0, updatedAt: t90 })).toBeNull();
  });

  it("잡이 없으면 null", () => {
    expect(terminalJobDurationMs(null)).toBeNull();
    expect(terminalJobDurationMs(undefined)).toBeNull();
  });

  it("시계 역행 등으로 updatedAt<createdAt이어도 음수가 아니라 0", () => {
    expect(terminalJobDurationMs({ status: "APPLIED", createdAt: t90, updatedAt: t0 })).toBe(0);
  });

  it("isTerminalJobStatus: 종결만 true", () => {
    expect(isTerminalJobStatus("APPLIED")).toBe(true);
    expect(isTerminalJobStatus("RUNNING")).toBe(false);
    expect(isTerminalJobStatus(null)).toBe(false);
  });
});

