  dataRev, onDataChanged, ...
}: { 
  ...
  dataRev?: number; onDataChanged?: () => void;
  ...
})
```

**Key useEffect watching dataRev (lines 452-457):**
```ts
const firstDataRev = useRef(true);
useEffect(() => {
  if (firstDataRev.current) { firstDataRev.current = false; return; }
  loadTree(); loadArchive(); loadMyQ();
}, [dataRev]); // Only triggers on dataRev changes (skips first mount)
```

