}
// 개인 위키(personal)는 '공용'이 본인뿐이라 승격 의미 없음 → 공통·룸에서만 버튼 노출.
const canPromote = !scope.startsWith("personal");
useEffect(() => { if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight; }, [messages, streaming, hidden]);

// 답변/오류 메시지를 ★질의를 시작한 룸(qScope)★에 전달한다. 그 사이 사용자가 다른 룸으로 갔으면
// 화면(messages)이 아니라 그 룸의 캐시에만 반영 → 답변이 엉뚱한 룸에 끼어들지 않는다.
function deliver(qScope: string, botMsg: Msg, newConvId?: number) {
  if (qScope === prevScopeRef.current) {
    if (newConvId != null) setConvId(newConvId);
    setMessages((m) => [...m, botMsg]);
  } else {
    const cur = cacheRef.current[qScope] ?? { messages: [], convId: null };
    cacheRef.current[qScope] = { messages: [...cur.messages, botMsg], convId: newConvId ?? cur.convId };
    persistCache();
  }
}

async function send(qOverride?: string) {
  const q = (qOverride ?? input).trim(); // 추천 질문 버튼은 qOverride로 전달(입력칸 비우지 않음)
  if (!q || streamingScopes.has(scope)) return; // 같은 룸에서 중복 전송만 막음(다른 룸 질의는 허용)
  const qScope = scope;      // ★이 질의가 속한 룸★ — 응답은 여기로만 간다
  const qConvId = convId;
  if (!qOverride) setInput("");
  const uid = Date.now();
  const now = () => new Date().toTimeString().slice(0, 5);
  setMessages((m) => [...m, { id: uid, role: "user", time: now(), text: q }]);
  setStreamingScopes((s) => new Set(s).add(qScope));
  // 응답 지연·연결 끊김으로 잠기지 않도록 타임아웃·중단 가드.
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 180_000); // 웹검색 다중 루프 고려 3분
  try {
    const res = await fetch("/api/chat", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ scope: qScope, question: q, conversationId: qConvId, web, model, includeCommon }),
      signal: ctrl.signal,
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || "요청 실패");
    const cites: Citation[] = (data.citations || []).map((c: { type?: string; label?: string; url?: string; path?: string; snippet?: string; scopeLabel?: string }, i: number) => ({
      id: `c${uid}-${i}`,
      label: c.label || "출처",
      type: c.type === "web" ? "web" : "wiki",
      url: c.url,
      path: c.path,
      snippet: c.snippet,
      scopeLabel: c.scopeLabel,
    }));
    deliver(qScope, { id: uid + 1, role: "bot", time: now(), text: data.answer, citations: cites, evidence: data.evidence, usage: data.usage, noGrounding: data.answered === false, web: data.web === true, fallback: data.fallback || undefined, usedModel: data.usedModel, usedProvider: data.usedProvider, reused: data.reused === true, queryId: data.queryId, promotable: data.promotable === true, suggestions: Array.isArray(data.suggestedQuestions) ? data.suggestedQuestions : undefined, budgetWarn: data.budgetWarn === true }, data.conversationId);
  } catch (e) {
    const msg = ctrl.signal.aborted
      ? "응답이 너무 오래 걸려 중단했어요. 다시 시도해 주세요."
      : toUserMessage(e);
    deliver(qScope, { id: uid + 1, role: "bot", time: now(), text: msg, citations: [], error: true, failedQ: q });
    if (!qOverride && qScope === scope) setInput((cur) => cur || q); // 입력 비었으면 질문 복구(수정·재시도 쉽게)
  } finally {
    clearTimeout(timer);
    setStreamingScopes((s) => { const n = new Set(s); n.delete(qScope); return n; });
  }
}

