const loadTree = useCallback(async () => {
  const reqScope = scope;
  try {
    const res = await fetch(`/api/wiki?scope=${encodeURIComponent(reqScope)}`);
    const d = await res.json();
    if (res.ok && reqScope === curScopeRef.current) { setFiles(d.files); setWikiScope(d.scope); setTypes(d.types || {}); setTitles(d.titles || {}); setUpdated(d.updated || {}); setAliasMap(d.aliasMap || {}); }
  } catch { /* noop */ }
}, [scope]);

// 교차-scope 링크 인덱스 로드 — 접근 가능한 모든 룸의 제목→경로(ACL=멤버 룸만). 자료/페이지 변경(dataRev) 시 갱신.
useEffect(() => {
  let alive = true;
  fetch("/api/wiki/links").then((r) => r.json()).then((d) => { if (alive && d.links) setCrossLinks(d.links); }).catch(() => { /* noop */ });
  return () => { alive = false; };
}, [dataRev]);

// 아카이브 목록 + 이 scope의 관리 권한(canManage) 로드.
const loadArchive = useCallback(async () => {
  const reqScope = scope;
  try {
    const res = await fetch(`/api/wiki/archive?scope=${encodeURIComponent(reqScope)}`);
    const d = await res.json();
    if (res.ok && reqScope === curScopeRef.current) { setArchived(d.pages || []); setCanManage(Boolean(d.canManage)); }
  } catch { /* noop */ }
}, [scope]);

// 내 비공개 질의 목록.
const loadMyQ = useCallback(async () => {
  const reqScope = scope;
  try {
    const res = await fetch(`/api/queries/mine?scope=${encodeURIComponent(reqScope)}`);
    const d = await res.json();
    if (res.ok && reqScope === curScopeRef.current) setMyQ(d.queries || []);
  } catch { /* noop */ }
}, [scope]);
// 비공개 질의 → 룸 공용으로 승격. 성공 시 목록·트리(queries 페이지 등장) 갱신.
const promoteMyQ = useCallback(async (id: number, anon: boolean) => {
  if (promotingId) return;
  setPromotingId(id);
  try {
    const r = await fetch(`/api/queries/${id}/promote`, {
      method: "POST", headers: { "content-type": "application/json" },
      body: JSON.stringify({ anonymous: anon }), // 익명 여부 전달(표시만 숨김·userId 감사 유지)
    });
    if (r.ok) await Promise.all([loadMyQ(), loadTree()]);
  } catch { /* noop */ } finally { setPromotingId(null); }
}, [promotingId, loadMyQ, loadTree]);

// 관리자 위키 정비(한글화) — SSH/k exec 대신 브라우저 클릭. 서버에서 정규화 실행 후 트리 갱신.
const runTidy = useCallback(async () => {
  if (tidyBusy) return;
  setTidyBusy(true); setTidyNote("정비 중…");
  try {
    const r = await fetch("/api/admin/maintenance", {
      method: "POST", headers: { "content-type": "application/json" },
      body: JSON.stringify({ scope }),
    });
    const d = await r.json();
    if (r.ok) { setTidyNote(`목차 ${d.regenerated}룸 재생성 · 한글화 ${d.fixed}건 · 색인 ${d.indexed ?? 0}건 ✓`); await loadTree(); }
    else setTidyNote(toUserMessage(d, "정비에 실패했어요. 잠시 후 다시 시도해 주세요."));
  } catch (e) { setTidyNote(toUserMessage(e, "정비에 실패했어요.")); } finally { setTidyBusy(false); }
}, [tidyBusy, loadTree, scope]);

// scope 바뀌면 트리(파일/제목)·아카이브만 다시 로드. 탭·활성·본문 캐시는 ★룸별로 유지★(초기화 안 함).
useEffect(() => {
  setFiles([]); setTypes({}); setTitles({}); setUpdated({}); setAliasMap({}); setArchived([]); setCanManage(false); setShowArchive(false); setMyQ([]);
  setEditing(null); setEditNote("");
