            <h1 className="wk-scope-name">{info.name}</h1>
            {info.description && <span className="wk-scope-desc" title={info.description}>{info.description}</span>}
            {info.kind === "project" && info.parentScope && (
              <span className="wk-scope-desc" title="상위 룸 — 이 룸 질의는 상위 룸 지식도 함께 봅니다">↳ 상위: {scopes.find((s) => s.id === info.parentScope)?.name ?? "상위 룸"}</span>
            )}
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexShrink: 0 }}>
            {/* 룸 설정 버튼은 ★모든 멤버★에게 노출(멤버는 멤버목록·나가기만, 소유자만 이름변경·강퇴·아카이브·초대 — 모달 내부에서 myRole로 분기). 아카이브 룸은 관리 불가라 숨김. */}
            {info.kind === "project" && !readOnly && (
              <button className="btn btn-ghost btn-sm" style={btnGhost} onClick={() => setInviteOpen(true)}><IconSettings size={13} />룸 설정</button>
            )}
          </div>
        </header>
        {/* 아카이브 룸은 위키 탭만 노출(읽기 전용) — 채팅·자료 탭은 숨긴다. */}
        <div className="wk-tabbar">
          {(readOnly ? TABS.filter((t) => t.id === "wiki") : TABS).map((t) => (
            <button key={t.id} className={`wk-tab${effTab === t.id ? " active" : ""}`} onClick={() => setTab(t.id)}>
              <t.Icon size={14} />{t.label}
            </button>
          ))}
        </div>
