          <div className="wk-readonly-banner">
            <IconLock size={14} />
            <span>보관된 룸입니다 · <b>읽기 전용</b>으로 위키만 열람할 수 있습니다.</span>
            {info.isOwner && (
              <button className="wk-restore-btn" onClick={restoreRoom} disabled={restoring}>
                <IconArrowBackUp size={13} />{restoring ? "복원 중…" : "복원"}
              </button>
            )}
          </div>
        )}
        <div className="wk-content">
          {/* 질의 탭은 항상 마운트(탭 전환에도 대화·입력·진행 상태 유지), 보일 때만 표시 */}
          <ChatTab scope={scope} meInitials={me.initials} hidden={effTab !== "chat"} onOpenWiki={openWikiPath} modelsRev={modelsRev} onDataChanged={() => setDataRev((r) => r + 1)} />
          {/* 자료 탭도 ★항상 마운트★(보일 때만 표시) — 탭 전환에도 업로드 모드·스테이징 큐 보존(② 해결) */}
          <MaterialsTab scope={scope} hidden={effTab !== "materials"} onOpenWiki={openWikiPath} modelsRev={modelsRev} dataRev={dataRev} onDataChanged={() => setDataRev((r) => r + 1)} />
          {/* 위키 탭도 항상 마운트(보일 때만 표시) — 메인 탭 전환에도 열린 위키 탭·스크롤·내용 유지 */}
          <WikiTab scope={scope} scopeName={info.name} target={wikiTarget} onConsumeTarget={() => setWikiTarget(null)} hidden={effTab !== "wiki"} readOnly={readOnly} dataRev={dataRev} onDataChanged={() => setDataRev((r) => r + 1)}
