const [convId, setConvId] = useState<number | null>(null);
const [input, setInput] = useState("");
const [web, setWeb] = useState(false);
const [includeCommon, setIncludeCommon] = useState(false); // ★옵트인★ 프로젝트 룸 질의에 회사 공통도 함께 검색
// ★룸(scope)별 진행 상태★ — '생각 중'·입력 잠금은 ★그 질의를 시작한 룸에서만★ 보이게(룸 전환·다른 룸 질의가 새지 않음).
const [streamingScopes, setStreamingScopes] = useState<Set<string>>(new Set());
const streaming = streamingScopes.has(scope); // 현재 보고 있는 룸이 답변 생성 중인가
const [models, setModels] = useState<ModelOpt[]>([]);
const [model, setModel] = useState<string>("");
const [defaultModelId, setDefaultModelId] = useState<string>(""); // 시스템 기본 모델 — 셀렉터 '기본' 배지용
const scrollRef = useRef<HTMLDivElement>(null);

// 선택 가능한 질의 모델 로드(로컬=선택 가능, Claude=결제 시). 기본=첫 enabled. no-store=항상 최신.
// modelsRev 변경(관리자가 설정에서 토글 후 모달 닫힘) 시 재조회해 최신 가용 모델을 반영.
useEffect(() => {
  fetch("/api/models", { cache: "no-store" }).then((r) => r.json()).then((d) => {
    const ms: ModelOpt[] = d.models || [];
    setModels(ms);
    setDefaultModelId(d.default || "");
    setModel((cur) => {
      if (cur && ms.some((m) => m.id === cur && m.enabled)) return cur; // 현재 선택이 여전히 유효하면 유지
      const def = d.default && ms.some((m) => m.id === d.default && m.enabled) ? d.default : null;
      return def || ms.find((m) => m.enabled)?.id || ""; // 아니면 기본/첫 enabled로
    });
  }).catch(() => { /* noop */ });
}, [modelsRev]);

// 웹검색: Claude(서버 web_search) + Gemini(Google Search 그라운딩)에서 가능. 로컬·Groq는 불가.
const selectedProvider = models.find((m) => m.id === model)?.provider;
const webSupported = selectedProvider === "anthropic" || selectedProvider === "gemini";
// 외부 전송(프라이버시 경고) 공급자: Gemini·Groq(OpenAI 호환)·codex(OpenAI)·claude-cli(구독→Anthropic). 데이터가 PC 밖으로 나간다.
const externalSelected = selectedProvider === "gemini" || selectedProvider === "openai-compat" || selectedProvider === "codex" || selectedProvider === "claude-cli";
useEffect(() => { if (!webSupported && web) setWeb(false); }, [webSupported, web]);

// 룸(scope)별 대화 보존 + sessionStorage 영속화.
// 탭/룸 전환은 물론, '검토 콘솔'·'계정 설정'처럼 별도 페이지로 이동했다 돌아와도(=AppShell 언마운트)
// 현재 룸의 질문·답변이 유지된다. (단 이동 시점에 '답변 생성 중'이던 요청은 취소되어 그 답은 못 받음)
const SS_KEY = "llmwiki_chat_v1";
const cacheRef = useRef<Record<string, { messages: Msg[]; convId: number | null }>>({});
const messagesRef = useRef(messages); messagesRef.current = messages;
const convIdRef = useRef(convId); convIdRef.current = convId;
const prevScopeRef = useRef(scope);
const savedOnceRef = useRef(false);
const persistCache = () => { try { sessionStorage.setItem(SS_KEY, JSON.stringify(cacheRef.current)); } catch { /* quota 등 무시 */ } };

// 마운트: sessionStorage에서 복원(페이지 이동/새로고침 후에도 현재 룸 대화 유지).
useEffect(() => {
  try {
    const raw = sessionStorage.getItem(SS_KEY);
    if (raw) {
      cacheRef.current = JSON.parse(raw) || {};
      const cur = cacheRef.current[scope];
      if (cur?.messages?.length) { setMessages(cur.messages); setConvId(cur.convId ?? null); }
    }
  } catch { /* noop */ }
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, []);

// 룸 전환: 이전 룸 저장 + 새 룸 복원.
useEffect(() => {
  const prev = prevScopeRef.current;
  if (prev === scope) return;
  cacheRef.current[prev] = { messages: messagesRef.current, convId: convIdRef.current };
  const restored = cacheRef.current[scope] ?? { messages: [], convId: null };
  setMessages(restored.messages);
  setConvId(restored.convId);
  setInput("");
  prevScopeRef.current = scope;
  persistCache();
}, [scope]);

// 메시지/대화 변경 시 현재 룸 저장(첫 마운트 저장은 건너뛰어 복원본을 보존).
useEffect(() => {
  if (!savedOnceRef.current) { savedOnceRef.current = true; return; }
  cacheRef.current[scope] = { messages: messages.slice(-100), convId };
  persistCache();
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [messages, convId]);

// 명시적 새 대화(세션 초기화) — convId를 비워 다음 질의가 새 대화로 시작.
function clearChat() {
  if (streaming) return;
  setMessages([]); setConvId(null); setInput("");
  delete cacheRef.current[scope];
  persistCache();
}
// 비공개 답 → 룸 공용으로 승격(계획 A6). 성공 시 그 메시지를 '공용화됨'으로 표시.
async function promote(m: Msg, anonymous = false) {
  if (!m.queryId || m.promoted) return;
  try {
    const res = await fetch(`/api/queries/${m.queryId}/promote`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ anonymous }) });
    if (!res.ok) return;
    setMessages((ms) => ms.map((x) => (x.id === m.id ? { ...x, promoted: true } : x)));
    onDataChanged?.(); // 새로 생긴 queries 페이지를 위키 탭 트리·내질의에 즉시 반영(새로고침 없이)
  } catch { /* noop */ }

