"use client";
import { useCallback, useEffect, useState } from "react";
import { IconBell, IconX } from "@tabler/icons-react";
import { kstStamp } from "@/lib/time";

// 인앱 알림 종🔔 (A-4 토대) — 안읽음 배지 + 드로어. 저빈도라 ★폴링★(60초)으로 충분(SSE 없음).
// 드로어를 열면 안읽음을 모두 읽음 처리. 항목 클릭 시 linkPath로 이동(있으면). 정기 잡(오래됨·다이제스트)이 알림을 생성.
interface Notif { id: number; type: string; title: string; body?: string | null; linkPath?: string | null; teamScope?: string | null; readAt?: string | null; createdAt: string }

export default function NotificationBell() {
  const [items, setItems] = useState<Notif[]>([]);
  const [unread, setUnread] = useState(0);
  const [open, setOpen] = useState(false);

  const load = useCallback(async () => {
    try {
      const r = await fetch("/api/notifications", { cache: "no-store" });
      if (r.ok) { const d = await r.json(); setItems(d.items || []); setUnread(d.unread || 0); }
    } catch { /* 네트워크 실패는 조용히 — 다음 폴링에서 복구 */ }
  }, []);

  useEffect(() => { void load(); const t = setInterval(() => void load(), 60_000); return () => clearInterval(t); }, [load]);

  const toggle = () => {
    setOpen((o) => {
      const next = !o;
      if (next && unread > 0) { // 열면 안읽음 모두 읽음 처리(낙관적 + 서버 반영)
        setUnread(0);
        setItems((p) => p.map((n) => (n.readAt ? n : { ...n, readAt: new Date().toISOString() })));
        void fetch("/api/notifications/read", { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }).catch(() => {});
      }
      return next;
    });
  };

  return (
    <div className="notif-wrap">
      <button className="notif-bell" onClick={toggle} title="알림" aria-label={`알림${unread > 0 ? ` (안읽음 ${unread})` : ""}`}>
        <IconBell size={15} />
        {unread > 0 && <span className="notif-badge">{unread > 99 ? "99+" : unread}</span>}
      </button>
      {open && (
        <>
          <div className="notif-backdrop" onClick={() => setOpen(false)} />
          <div className="notif-drawer" role="dialog" aria-label="알림">
            <div className="notif-head"><span>알림</span><button className="modal-x" onClick={() => setOpen(false)} aria-label="닫기"><IconX size={15} /></button></div>
            {items.length === 0 ? (
              <div className="notif-empty">새 알림이 없습니다.</div>
            ) : (
              <div className="notif-list">
                {items.map((n) => (
                  <button key={n.id} className={`notif-item${n.readAt ? "" : " unread"}`}
                    onClick={() => { if (n.linkPath) window.location.assign(n.linkPath); else setOpen(false); }}>
                    <div className="notif-item-title">{n.title}</div>
                    {n.body && <div className="notif-item-body">{n.body}</div>}
                    <div className="notif-item-time">{kstStamp(new Date(n.createdAt))} KST</div>
                  </button>
                ))}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}
